def _dkg_event_round(dkg_id: str, request_id: object) -> int | None:
    """由事件 request_id 解析其所属轮次。

    基线轮为会话 id 本身（轮次 1）；派生轮为 ``"<id>/<round>"``。
    无法解析返回 None（不可对账现场）。"""
    if not isinstance(request_id, str):
        return None
    if request_id == dkg_id:
        return 1
    prefix = dkg_id + "/"
    if request_id.startswith(prefix):
        tail = request_id[len(prefix):]
        if tail.isdigit():
            return int(tail)
    return None

