                "state mismatch"
            )
    else:  # replace
        # replace 仅限 commit/share 两方阶段
        if prev["state"] not in ("commit", "share"):
            raise RecoveryError(
                f"wallet {wallet_id!r} dkg session {dkg_id!r} replace is "
                "only allowed in the commit/share stages"
