            raise RecoveryError(
                f"wallet {wallet_id!r} dkg session {dkg_id!r} has a "
                "malformed replacement key"
            )
        target = self._new_round(dkg_id, round_no)
        # 换槽：沿用上一轮节点序列，把 node 所在槽位换成
        # replacement/key；committed/shared 已为空，节点视为已注册，
        # 目标轮从 commit 阶段重新推进。
        target["nodes"] = [
