        if details["state"] != "commit":
            raise RecoveryError(
                f"wallet {wallet_id!r} dkg session {dkg_id!r} replace "
                "state mismatch"
            )
    rounds[round_no] = target
    failovers[round_no] = (action, node, replacement, key)
